//META {"title":"Cyclic groups, Z_n and quotients: clock arithmetic and cosets","desc":"Z_n is the clock with n hours; the subgroup ⟨d⟩ generated by a divisor d of n has n/d elements and the quotient Z_n/⟨d⟩ ≅ Z_d. Pick n and a generator g: the cyclic subgroup ⟨g⟩, its order n/gcd(g, n) and the cosets are drawn on the clock (each coset a colour). The second panel is the direct product Z_m × Z_n as a grid on a torus: it is cyclic exactly when gcd(m, n) = 1 (then Z_m × Z_n ≅ Z_{mn}), and the element orders are coloured.","vault":"GT","chapters":["GT02 Homomorphisms Normal Subgroups and Quotients","GT03 Cyclic and Abelian Groups and Direct Products"],"tryit":"n = 12, g = 4: the subgroup {0, 4, 8} has order 3 and index 4 (four cosets). The quotient has 4 elements: Z₁₂/⟨4⟩ ≅ Z₄. Product: Z₃ × Z₄ (gcd 1) has an element of order 12 so it is cyclic ≅ Z₁₂; Z₂ × Z₄ (gcd 2) has no element of order 8: not cyclic."}
ui.gridOf(2);const P1=ui.canvas(340,{xmin:-1.5,xmax:1.5,ymin:-1.5,ymax:1.5,axes:false,equal:true,title:'the clock Z_n, subgroup ⟨g⟩ and its cosets'});const P2=ui.canvas(340,{xmin:0,xmax:1,ymin:0,ymax:1,axes:false,title:'the product Z_m × Z_n: colour = element order'});
const sn=ui.slider('n',2,36,1,12,draw),sg=ui.slider('generator g',1,35,1,4,draw),sm=ui.slider('m (product)',2,12,1,3,draw),sk=ui.slider('n′ (product)',2,12,1,4,draw);
const out=ui.readout();const gcd=(a,b)=>b?gcd(b,a%b):a;
function draw(){const n=sn.value,g=sg.value%n||n%n;const gg=g%n;const d=gcd(gg===0?n:gg,n);const H=[];for(let k=0;k<n/d;k++)H.push((gg*k)%n);const Hs=new Set(H);P1.clear();const pos=i=>[1.15*Math.sin(2*Math.PI*i/n),1.15*Math.cos(2*Math.PI*i/n)];const cosets=[];const col=new Array(n).fill(-1);for(let a=0;a<n;a++){if(col[a]>=0)continue;const id=cosets.length;const c=[];for(const h of H){const x=(a+h)%n;col[x]=id;c.push(x)}cosets.push(c)}
 const cc=id=>`hsl(${Math.round(360*id/cosets.length)},70%,55%)`;const th=M.linspace(0,2*Math.PI,200);P1.line(th.map(t=>1.15*Math.cos(t)),th.map(t=>1.15*Math.sin(t)),C.grid,1.5);
 // draw the cyclic subgroup polygon
 if(H.length>1){const hs=H.slice().sort((a,b)=>a-b);const pts=hs.map(pos);P1.poly(pts,'rgba(235,104,52,0.10)',C.orange,2)}
 for(let i=0;i<n;i++){const [x,y]=pos(i);P1.circle(x,y,Math.max(8,22-n*0.5),cc(col[i]),Hs.has(i)?C.ink:'#888',Hs.has(i)?3:1);P1.text(String(i),x*1.0,y,'#000','center','bold '+Math.max(8,13-n*0.15)+'px system-ui')}
 P1.text('Z_'+n+'  ⟨'+gg+'⟩',0,0.1,C.ink,'center','bold 16px system-ui');P1.text('order '+H.length+', index '+n/H.length,0,-0.15,C.orange,'center','14px system-ui');
 P2.clear();const m=sm.value,k=sk.value,G2=P2.g,Wd=P2.w-40,Hd=P2.h-60,cs=Math.min(Wd/m,Hd/k);const lcm=(a,b)=>a/gcd(a,b)*b;let maxo=0;const ords=[];for(let a=0;a<m;a++)for(let b=0;b<k;b++){const o=lcm(m/gcd(a||m,m),k/gcd(b||k,k));ords.push([a,b,o]);maxo=Math.max(maxo,o)}
 ords.forEach(([a,b,o])=>{G2.fillStyle=`hsl(${Math.round(260-240*o/Math.max(maxo,1))},65%,60%)`;G2.fillRect(30+a*cs,30+b*cs,cs-2,cs-2);if(cs>18)P2.ptext(String(o),30+a*cs+cs/2,30+b*cs+cs/2,'#000','center','11px system-ui')});
 P2.ptext('(a, b) ∈ Z_'+m+' × Z_'+k+': entry = order of (a, b) = lcm(m/gcd(a,m), n′/gcd(b,n′))',20,12,C.muted,'left','11px system-ui');
 const cyc=gcd(m,k)===1;
 out.textContent=`Z_${n}: ⟨${gg}⟩ = {${H.slice().sort((a,b)=>a-b).join(', ')}}  order n/gcd(g,n) = ${n}/${gcd(gg||n,n)} = ${H.length}   ${cosets.length} cosets (index ${cosets.length}): ${cosets.map(c=>'{'+c.slice().sort((a,b)=>a-b).join(',')+'}').join('  ')}   quotient Z_${n}/⟨${gg}⟩ ≅ Z_${cosets.length} (abelian ⇒ every subgroup is normal)\nproduct Z_${m} × Z_${k}: order ${m*k}, maximal element order ${maxo}   ${cyc?'gcd = 1 → generated by (1,1), CYCLIC ≅ Z_'+m*k:'gcd = '+gcd(m,k)+' > 1 → no element of order '+m*k+': NOT cyclic (exponent = lcm = '+lcm(m,k)+')'}`}
draw();ui.note('GT02/GT03: ⟨g⟩ ≤ Z_n has order n/gcd(g,n); Z_n/⟨d⟩ ≅ Z_d for d | n (first isomorphism theorem applied to x ↦ x mod d); Z_m × Z_n ≅ Z_{mn} iff gcd(m,n) = 1 (Chinese remainder theorem).');
